import os, uuid, time, logging, datetime as dt
import bcrypt, jwt, redis
from flask import Flask, request, jsonify
from werkzeug.exceptions import HTTPException

BASE = '/app'
os.makedirs(BASE + '/logs', exist_ok=True)
logging.basicConfig(filename=BASE + '/logs/app.log', level=logging.INFO,
                    format='%(asctime)s %(levelname)s api: %(message)s')
log = logging.getLogger('api')

with open(BASE + '/keys/private.pem') as f:
    PRIVATE = f.read()
with open(BASE + '/keys/public.pem') as f:
    PUBLIC = f.read()

ISSUER = 'rsa-jwt-api'
ACCESS_TTL = dt.timedelta(minutes=15)
REFRESH_TTL = dt.timedelta(days=7)
REDIS_HOST = os.environ.get('REDIS_HOST', 'localhost')
r = redis.Redis(host=REDIS_HOST, port=6379, decode_responses=True)
USERS = {'admin': bcrypt.hashpw(b'password123', bcrypt.gensalt()).decode()}

app = Flask(__name__)


@app.errorhandler(Exception)
def on_error(e):
    if isinstance(e, HTTPException):
        log.error('%s %s -> %s %s', request.method, request.path, e.code, e.description)
        return jsonify(error=e.description), e.code
    log.exception('unhandled error on %s', request.path)
    return jsonify(error='internal server error'), 500


def make_token(sub, ttype, ttl):
    now = dt.datetime.now(dt.timezone.utc)
    claims = {'iss': ISSUER, 'sub': sub, 'iat': now, 'exp': now + ttl,
              'jti': str(uuid.uuid4()), 'type': ttype}
    return jwt.encode(claims, PRIVATE, algorithm='RS256')


def verify(token):
    return jwt.decode(token, PUBLIC, algorithms=['RS256'], issuer=ISSUER,
                      options={'require': ['exp', 'iat', 'jti', 'sub', 'iss']})


def check(token, expected_type=None):
    try:
        claims = verify(token)
    except jwt.ExpiredSignatureError:
        return None, ('token expired', 401)
    except jwt.InvalidTokenError as e:
        return None, ('invalid token: ' + str(e), 401)
    if expected_type and claims.get('type') != expected_type:
        return None, ('wrong token type', 401)
    if r.exists('blacklist:' + claims['jti']):
        return None, ('token revoked', 403)
    return claims, None


@app.post('/auth/login')
def login():
    body = request.get_json(silent=True) or {}
    user = body.get('username', '')
    pw = body.get('password', '')
    h = USERS.get(user)
    if not h or not bcrypt.checkpw(pw.encode(), h.encode()):
        log.warning('failed login for user %s', user)
        return jsonify(error='invalid credentials'), 401
    access = make_token(user, 'access', ACCESS_TTL)
    refresh = make_token(user, 'refresh', REFRESH_TTL)
    log.info('login ok for user %s', user)
    return jsonify(access_token=access, refresh_token=refresh, token_type='Bearer',
                   expires_in=int(ACCESS_TTL.total_seconds())), 200


@app.post('/auth/refresh')
def refresh():
    body = request.get_json(silent=True) or {}
    tok = body.get('refresh_token')
    if not tok:
        return jsonify(error='refresh_token required'), 400
    claims, err = check(tok, 'refresh')
    if err:
        log.warning('refresh rejected: %s', err[0])
        return jsonify(error=err[0]), err[1]
    access = make_token(claims['sub'], 'access', ACCESS_TTL)
    return jsonify(access_token=access, token_type='Bearer',
                   expires_in=int(ACCESS_TTL.total_seconds())), 200


@app.post('/auth/revoke')
def revoke():
    body = request.get_json(silent=True) or {}
    tok = body.get('token')
    if not tok:
        return jsonify(error='token required'), 400
    try:
        claims = verify(tok)
    except jwt.ExpiredSignatureError:
        return jsonify(error='token expired'), 401
    except jwt.InvalidTokenError as e:
        return jsonify(error='invalid token: ' + str(e)), 401
    ttl = int(claims['exp'] - time.time())
    if ttl > 0:
        r.setex('blacklist:' + claims['jti'], ttl, claims['sub'])
    log.info('revoked jti %s', claims['jti'])
    return jsonify(message='revoked', jti=claims['jti']), 200


@app.get('/auth/validate')
def validate():
    auth = request.headers.get('Authorization', '')
    tok = auth[7:] if auth.startswith('Bearer ') else request.args.get('token')
    if not tok:
        return jsonify(valid=False, error='missing token'), 401
    claims, err = check(tok)
    if err:
        log.warning('validation failed: %s', err[0])
        return jsonify(valid=False, error=err[0]), err[1]
    return jsonify(valid=True, claims=claims), 200


@app.get('/auth/public-key')
def public_key():
    return PUBLIC, 200, {'Content-Type': 'application/x-pem-file'}


if __name__ == '__main__':
    app.run(host='0.0.0.0', port=5000)
