#!/usr/bin/env python3
import argparse, json, logging, os, sys, time
import requests

BASE = '/app'
TOKENS = BASE + '/tokens.json'
API = os.environ.get('API_URL', 'http://localhost:5000')
os.makedirs(BASE + '/logs', exist_ok=True)
logging.basicConfig(filename=BASE + '/logs/app.log', level=logging.INFO,
                    format='%(asctime)s %(levelname)s cli: %(message)s')
log = logging.getLogger('cli')


def load():
    if not os.path.exists(TOKENS):
        return {}
    with open(TOKENS) as f:
        return json.load(f)


def save(d):
    with open(TOKENS, 'w') as f:
        json.dump(d, f, indent=2)


def post(path, **body):
    return requests.post(API + path, json=body, timeout=10)


def validate_token(tok):
    return requests.get(API + '/auth/validate',
                        headers={'Authorization': 'Bearer ' + tok}, timeout=10)


def do_login(user, pw):
    r = post('/auth/login', username=user, password=pw)
    if r.status_code != 200:
        log.error('login failed for %s: %s %s', user, r.status_code, r.text)
        print('login failed:', r.status_code, r.text, file=sys.stderr)
        return False
    d = r.json()
    save({'username': user, 'access_token': d['access_token'],
          'refresh_token': d['refresh_token']})
    print('tokens acquired and saved to', TOKENS)
    return True


def do_refresh(d):
    if not d.get('refresh_token'):
        return False
    r = post('/auth/refresh', refresh_token=d['refresh_token'])
    if r.status_code != 200:
        log.error('refresh failed: %s %s', r.status_code, r.text)
        print('refresh failed:', r.status_code, r.text, file=sys.stderr)
        return False
    d['access_token'] = r.json()['access_token']
    save(d)
    print('access token refreshed')
    return True


def cmd_acquire(args):
    return 0 if do_login(args.username, args.password) else 1


def cmd_validate(args):
    d = load()
    if 'access_token' not in d:
        print('no tokens found; run acquire first', file=sys.stderr)
        return 1
    r = validate_token(d['access_token'])
    if r.status_code == 401 and d.get('refresh_token'):
        print('access token expired or invalid; attempting refresh')
        if do_refresh(d):
            r = validate_token(d['access_token'])
    print(r.status_code, r.text)
    if r.status_code == 200:
        print('VALID')
        return 0
    print('INVALID (expired)' if r.status_code == 401 else 'INVALID (revoked)')
    if r.status_code == 401:
        log.warning('validate: token expired or invalid')
    return 3 if r.status_code == 403 else 1


def cmd_revoke(args):
    d = load()
    keys = ['access_token', 'refresh_token'] if args.which == 'both' else [args.which + '_token']
    for k in keys:
        if k not in d:
            continue
        r = post('/auth/revoke', token=d[k])
        print(k, r.status_code, r.text)
        if r.status_code == 200:
            log.info('revoked %s', k)
        else:
            log.error('revoke of %s failed: %s %s', k, r.status_code, r.text)
        if r.status_code in (200, 401):
            d.pop(k, None)
    save(d)
    return 0


def cmd_retry(args):
    for i in range(1, args.attempts + 1):
        d = load()
        if d.get('access_token') and validate_token(d['access_token']).status_code == 200:
            print('tokens valid; nothing to retry')
            return 0
        if do_refresh(d):
            return 0
        if do_login(args.username, args.password):
            return 0
        wait = 2 ** (i - 1)
        print('attempt %d failed; retrying in %ds' % (i, wait))
        time.sleep(wait)
    print('giving up after %d attempts' % args.attempts, file=sys.stderr)
    return 1


def main():
    p = argparse.ArgumentParser(description='JWT auth CLI')
    sub = p.add_subparsers(dest='cmd', required=True)
    a = sub.add_parser('acquire')
    a.add_argument('--username', default='admin')
    a.add_argument('--password', default='password123')
    sub.add_parser('validate')
    rv = sub.add_parser('revoke')
    rv.add_argument('--which', choices=['access', 'refresh', 'both'], default='both')
    rt = sub.add_parser('retry')
    rt.add_argument('--attempts', type=int, default=3)
    rt.add_argument('--username', default='admin')
    rt.add_argument('--password', default='password123')
    args = p.parse_args()
    handlers = {'acquire': cmd_acquire, 'validate': cmd_validate,
                'revoke': cmd_revoke, 'retry': cmd_retry}
    try:
        return handlers[args.cmd](args)
    except requests.RequestException as e:
        log.error('API unreachable at %s: %s', API, e)
        print('error: API unreachable at', API, file=sys.stderr)
        return 2


if __name__ == '__main__':
    sys.exit(main())
